from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P08','AP_READY=1','BAD_ENTRY_VALID=1','BAD_RECLAIM=1','BAD_USE_VAL=00','GOOD_USERS_DURING=01','GOOD_RECLAIM_DURING=0','GOOD_USE_VAL=7E','GOOD_USERS_AFTER=00','GOOD_RECLAIM_AFTER=1','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1']),'entry_validation_not_lifetime_protection':all(x in trace for x in ['BAD_ENTRY_VALID=1','BAD_RECLAIM=1','BAD_USE_VAL=00']),'inflight_participation_blocks_reclaim':all(x in trace for x in ['GOOD_USERS_DURING=01','GOOD_RECLAIM_DURING=0','GOOD_USE_VAL=7E','GOOD_USERS_AFTER=00','GOOD_RECLAIM_AFTER=1'])};out={'format':'C005_P08_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n',encoding='utf-8',newline='\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
